const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();
pres.layout = 'LAYOUT_WIDE';

// Slide 1: Title
const s1 = pres.addSlide();
s1.addText('团队协作', { x: 0.8, y: 1.5, w: 11, fontSize: 44, bold: true, fontFace: '微软雅黑', color: '1B4F72', align: 'center' });
s1.addText('打造高效、信任、共赢的团队', { x: 0.8, y: 2.8, w: 11, fontSize: 22, fontFace: '微软雅黑', color: '555555', align: 'center' });

// Slide 2: Why teamwork matters
const s2 = pres.addSlide();
s2.addText('为什么团队协作至关重要', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, fontFace: '微软雅黑', color: '1B4F72' });
s2.addText('• 复杂问题需要多元视角与技能互补\n• 协作能显著提升创新速度与决策质量\n• 高信任团队员工敬业度高出 76%\n• 减少信息孤岛，降低重复劳动成本', { x: 0.8, y: 1.3, w: 11, fontSize: 20, fontFace: '微软雅黑', lineSpacingMultiple: 1.5, color: '333333' });

// Slide 3: Core principles
const s3 = pres.addSlide();
s3.addText('高效协作的四大支柱', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, fontFace: '微软雅黑', color: '1B4F72' });
s3.addText('1. 清晰目标 — 共同愿景与可衡量里程碑\n2. 开放沟通 — 透明反馈、积极倾听、心理安全\n3. 角色明确 — 责任到人、权责对等、避免灰色地带\n4. 互信文化 — 容错机制、认可贡献、庆祝小胜', { x: 0.8, y: 1.3, w: 11, fontSize: 20, fontFace: '微软雅黑', lineSpacingMultiple: 1.5, color: '333333' });

// Slide 4: Practical methods
const s4 = pres.addSlide();
s4.addText('落地实践方法', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, fontFace: '微软雅黑', color: '1B4F72' });
s4.addText('• 每日站会 / 周复盘：同步进展、暴露阻塞\n• 共享看板（Kanban）：可视化任务流转与瓶颈\n• RACI 矩阵：厘清谁负责、谁审批、谁咨询、谁知悉\n• 异步文档优先：减少会议依赖，保留可追溯记录\n• 定期团建与一对一：建立人际连接与心理安全', { x: 0.8, y: 1.3, w: 11, fontSize: 20, fontFace: '微软雅黑', lineSpacingMultiple: 1.5, color: '333333' });

// Slide 5: Summary & call to action
const s5 = pres.addSlide();
s5.addText('从今天开始行动', { x: 0.6, y: 0.4, w: 11, fontSize: 28, bold: true, fontFace: '微软雅黑', color: '1B4F72' });
s5.addText('✓ 本周发起一次跨职能对齐会\n✓ 为团队建立共享目标看板\n✓ 每人写下"我能如何更好地支持队友"\n✓ 下次复盘加入"协作改进"固定议题\n\n协作不是天赋，而是可以练习的习惯。', { x: 0.8, y: 1.3, w: 11, fontSize: 20, fontFace: '微软雅黑', lineSpacingMultiple: 1.5, color: '333333' });

pres.writeFile({ fileName: '/workspace/团队协作.pptx' }).then(() => console.log('done'));
